"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([[75499],{28453:(e,n,a)=>{a.d(n,{R:()=>r,x:()=>l});var t=a(96540);const i={},o=t.createContext(i);function r(e){const n=t.useContext(o);return t.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function l(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),t.createElement(o.Provider,{value:n},e.children)}},75590:(e,n,a)=>{a.r(n),a.d(n,{assets:()=>s,contentTitle:()=>l,default:()=>p,frontMatter:()=>r,metadata:()=>t,toc:()=>c});const t=JSON.parse('{"id":"qiangguo/geneticscience","title":"","description":"The relationship between weapons and people has always been a focus of military science research. Emphasizing human will and agency led to strategies like people\'s war and guerrilla warfare -- methods of fighting from a position of weapons inferiority. But just as every law has its scope of applicability, people\'s war and guerrilla warfare also have their limits. The development of genetic science will bring people\'s war and guerrilla warfare face to face with obsolescence.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/qiangguo/geneticscience.md","sourceDirName":"qiangguo","slug":"/qiangguo/geneticscience","permalink":"/qiangguo/geneticscience","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"geneticscience","title":"","hide_table_of_contents":true},"sidebar":"qiangguoSidebar","previous":{"title":"\u8bba\u575b\uff0c\u6c38\u8fdc\u90fd\u4e0d\u8fc7\u662f\u4e00\u4e2a\u516c\u5171\u5395\u6240\uff01","permalink":"/qiangguo/forumpubliclavatory"},"next":{"title":"\u6252\u4e86\u5de6\u6d3e\u7684\u76ae\uff0c\u4ece\u6c6a\u7cbe\u536b\u5230\u9ec4\u91d1\u9ad8\uff01","permalink":"/qiangguo/wjw2hjg"}}');var i=a(74848),o=a(28453);const r={id:"geneticscience",title:"",hide_table_of_contents:!0},l="The Development of Genetic Science Will Render People's War and Guerrilla Warfare Obsolete",s={},c=[];function h(e){const n={h1:"h1",header:"header",p:"p",...(0,o.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(n.header,{children:(0,i.jsx)(n.h1,{id:"the-development-of-genetic-science-will-render-peoples-war-and-guerrilla-warfare-obsolete",children:"The Development of Genetic Science Will Render People's War and Guerrilla Warfare Obsolete"})}),"\n",(0,i.jsx)(n.p,{children:"The relationship between weapons and people has always been a focus of military science research. Emphasizing human will and agency led to strategies like people's war and guerrilla warfare -- methods of fighting from a position of weapons inferiority. But just as every law has its scope of applicability, people's war and guerrilla warfare also have their limits. The development of genetic science will bring people's war and guerrilla warfare face to face with obsolescence."}),"\n",(0,i.jsx)(n.p,{children:"The premise of human will and agency triumphing over weapons is that human will and agency are self-determined. But according to materialist thinking, the ultimate basis of human will and agency is material. Current developments in genetic science have provided one piece of evidence after another for this materialist proposition. Everything including human thought, personality, and more ultimately has a reasonable explanation at the genetic level."}),"\n",(0,i.jsx)(n.p,{children:"Once genetic technology advances to the point of completely understanding the biochemical processes by which genes or other material substances affect human will and agency, the emergence of a genetic weapon capable of controlling these processes would be entirely natural. Consider this: fearlessness in the face of death may be nothing more than a biochemical process controlled by a genetic program. With the appropriate modifications, a traitor's will could become a hero's will, and vice versa."}),"\n",(0,i.jsx)(n.p,{children:"In other words, as long as we uphold materialism, or if so-called materialism is truly correct, then ultimately weapons triumphing over human will and agency is an inevitability. Once this occurs, the danger of people's war and guerrilla warfare becoming obsolete would not be surprising at all. From this, we are clearly told: if people's war and guerrilla warfare represent solutions for the weak defeating the strong in the era of hot weapons military thought, then in the genetic age, all of this will ultimately and completely fail."}),"\n",(0,i.jsx)(n.p,{children:"The genetic age will be the age of the strong. Once the gap between strong and weak reaches a certain threshold, the weak will find all methods useless. Like a herd of elephants or monkeys -- even with the most brilliant strategies, facing human beings armed with even cold weapons would be futile. Therefore, technology is paramount. Stop placing excessive hope in human will and agency: in the genetic age, weapons are king."})]})}function p(e={}){const{wrapper:n}={...(0,o.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(h,{...e})}):h(e)}}}]);